/**
 *
 * Popover is a container component positioned as connected to its target.
 *
 * [Live Demo](https://primevue.dev/popover)
 *
 * @module popoverstyle
 *
 */
import type { BaseStyle, BaseStyleModule } from '@primevue/core/base/style';

export enum PopoverClasses {
    /**
     * Class name of the root element
     */
    root = 'p-popover',
    /**
     * Class name of the content element
     */
    content = 'p-popover-content'
}

export interface PopoverStyle extends BaseStyle {}

declare const PopoverStyle: BaseStyleModule;

export default PopoverStyle;
